INSERT INTO veloryz_studio.query_contracts (key,query) VALUES (encode(sha256(convert_to($q$UPDATE veloryz_studio.studio_client_projects AS p SET progress=COALESCE((SELECT ROUND(100.0*COUNT(*) FILTER (WHERE state='done')/NULLIF(COUNT(*),0))::integer FROM veloryz_studio.studio_client_items WHERE project_id=p.id AND type='milestone'),p.progress),next_step=COALESCE((SELECT title FROM veloryz_studio.studio_client_items WHERE project_id=p.id AND type='milestone' AND state<>'done' ORDER BY created_at ASC,title ASC LIMIT 1),p.next_step),updated_at=? WHERE p.id=? RETURNING id,progress,next_step$q$,'UTF8')),'hex'),$q$UPDATE veloryz_studio.studio_client_projects AS p SET progress=COALESCE((SELECT ROUND(100.0*COUNT(*) FILTER (WHERE state='done')/NULLIF(COUNT(*),0))::integer FROM veloryz_studio.studio_client_items WHERE project_id=p.id AND type='milestone'),p.progress),next_step=COALESCE((SELECT title FROM veloryz_studio.studio_client_items WHERE project_id=p.id AND type='milestone' AND state<>'done' ORDER BY created_at ASC,title ASC LIMIT 1),p.next_step),updated_at=? WHERE p.id=? RETURNING id,progress,next_step$q$) ON CONFLICT (key) DO NOTHING;